"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/contact/variants/01-routing";
import View1 from "./components/contact/variants/02-split";
const variants={"routing":View0,"split":View1};
export interface ArtemisContactFormProps { className?: string; variant?: "routing" | "split"; }
export function ArtemisContactForm({className,variant="routing"}:ArtemisContactFormProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
